-- lyric previews from LRCLIB (scripts/fetch-previews.mjs). Safe to re-run; never overwrites an existing preview.
alter table public.songs add column if not exists preview text check (char_length(preview) <= 200);


update public.songs set preview = v.preview from (values
('a loi|double2t', 'Tại vì thích em nhiều quá nhưng em lại nói là "à lôi" Cũng định solo Hiphop cùng với trai bản nhưng mà thôi Anh gửi vào trong câu rap cho em dính cả thính, cả mồi Nhà em có mấy quả'),
('thanh pho buon|dan nguyen', 'Thành phố nào nhớ không em Nơi chúng mình tìm phút êm đềm Thành phố nào vừa đi đã mỏi Đường quanh co quyện gốc thông già Chiều đan tay nghe nắng chan hoà Nắng hôn nhẹ làm hồng môi '),
('sau tim thiep hong|quang le', 'Từ lúc quen nhau chưa nói một lời gì, tỏ tình ta mến nhau Nhiều đêm ngắm sao mà ước duyên mình bền lâu, suốt đời tình khắc sâu Nhớ thương đầy vơi, mộng thấy ai mỉm cười, làn môi xi'),
('noi buon hoa phuong|nhu quynh', 'Mỗi năm đến hè lòng man mác buồn Chín mươi ngày qua chứa chan tình thương Ngày mai xa cách hai đứa hai nơi Phút gần gũi nhau mất rồi Tạ từ là hết người ơi Tiếng ve nức nở buồn hơn '),
('pho dem|nhu quynh', 'Phố đêm đèn mờ giăng giăng Màu trắng như vì sao gối đầu ngủ yên Phố đêm nhiều lần suy tư Ghi nhớ còn trong đời những ngày thương tích lớn Mây đen làm úa trăng gầy Cho nên còn tiếng'),
('vung la me bay|nhu quynh', 'Nhìn lá me bay nhớ kỷ niệm hai chúng mình Ngày đó quen nhau vương chút tình trên tóc mây Đôi mắt thơ ngây, hoa nắng ươm đầy Đẹp tựa như lá me bay nên tình anh trót vay Ngày đó yêu '),
('duyen phan|nhu quynh', 'Phận là con gái Chưa một lần yêu ai Nhìn về tương lai mà thấy như sông rộng đường dài Cảnh nhà neo đơn Bầy em chưa lớn trĩu đôi vai gánh nhọc nhằn Thầy mẹ thương em Nhờ tìm người s'),
('chuyen hoa sim|nhu quynh', 'Rừng hoang đẹp nhất hoa màu tím Chuyện tình thương nhất chuyện hoa sim Có người con gái xuân vời vợi Tóc còn ngăn ngắn chưa đầy búi Ngày xưa nàng vẫn yêu màu tím Chiều chiều lên nh'),
('thuong ly biet|chu thuy quynh', 'Đêm nay mình ta uống ánh trăng say trong đêm buồn Biết anh không còn yêu nhưng rời đi em chẳng muốn Lặng nhìn anh quay bước nước mắt em cũng khẽ tuôn Buông đôi tay níu kéo cũng đã '),
('hoa no khong mau|hoai lam', 'Ϲhỉ là nỗi nhớ mãi đứng sau cuộc tình đã lỡ Ϲhỉ là cơn mơ cuốn theo cả một trời thương nhớ Ϲhỉ là nỗi đau thổn thức, chỉ là nhói thêm một chút Ϲhỉ là nước mắt cứ rưng rưng Tìm về k'),
('buon lam chi em oi|hoai lam', 'Buồn làm chi em ơi lá xanh rồi cũng phai màu Ngỡ duyên mình bền lâu ai ngờ lại xa cách nhau Trăng treo trên mái đầu, tâm tư nên âu sầu Qua bao nhiêu dãi dầu mà lại nỡ qua cầu sang '),
('co chang trai viet len cay|phan manh quynh', 'Có chàng trai viết lên cây Lời yêu thương cô gái ấy Mối tình như gió như mây Nhiều năm trôi qua vẫn thấy Giống như bức tranh vẽ bằng dịu êm ngày thơ Có khi trong tiềm thức ngỡ là m'),
('vo nguoi ta|phan manh quynh', 'Tấm thiệp mời trên bàn Thời gian địa điểm rõ ràng Lại một đám mừng ở trong làng Ngó tên bỗng dưng thấy hoang mang Rồi ngày cưới rộn ràng khắp vùng Ai theo chân ai tới già trẻ đi cù'),
('nhat|phan manh quynh', 'Ta từng là lẽ sống Ta từng là ánh sáng nơi nhau Nhưng điều luôn nói trước đây, cho rằng chuyện chẳng đổi thay Hôm nay nên xem lại Ta chạy theo ý nghĩ riêng Ta bận tâm những thứ xun'),
('ngay chua giong bao|bui lan huong', 'Vì ta yêu nhau như cơn sóng vỗ Quẩn quanh bao năm không buông mặt hồ Thuyền anh đi xa bờ thì em vẫn dõi chờ Duyên mình dịu êm thơ rất thơ Và anh nâng niu em như đóa hoa Còn em xem '),
('chac ai do se ve|son tung m-tp', 'Anh tìm nỗi nhớ Anh tìm quá khứ Nhớ lắm kí ức anh và em Trả lại anh yêu thương ấy Xin người hãy về nơi đây Bàn tay yếu ớt cố níu em ở lại Những giọt nước mắt Lăn dài trên mi Cứ thế'),
('em cua ngay hom qua|son tung m-tp', 'Liệu rằng chia tay trong em có quên được câu ca Tình yêu khi xưa em trao cho anh đâu nào phôi pha Đừng lừa dối con tim anh em sẽ không buông tay anh được đâu mà Gạt nước mắt yếu đu'),
('noi nay co anh|son tung m-tp', 'Em là ai từ đâu bước đến nơi đây dịu dàng chân phương (dịu dàng chân phương) Em là ai tựa như ánh nắng ban mai ngọt ngào trong sương (ngọt ngào trong sương) Ngắm em thật lâu, con t'),
('lac troi|son tung m-tp', 'Người theo hương hoa mây mù giăng lối Làn sương khói phôi phai đưa bước ai xa rồi Đơn côi mình ta vấn vương Hồi ức, trong men say chiều mưa buồn Ngăn giọt lệ ngừng khiến khoé mi sầ'),
('chay ngay di|son tung m-tp', 'Good boy Từng phút cứ mãi trôi xa phai nhòa dần kí ức giữa đôi ta Từng chút nỗi nhớ hôm qua đâu về lạc bước cứ thế phôi pha Con tim giờ không cùng chung đôi nhịp Nụ cười lạnh băng '),
('hay trao cho anh|son tung m-tp', '"Hãy trao cho anh" Exactly! Trao cho anh, trao cho anh đê Trao cho anh, trao cho anh đê Tay chân đâu hết rồi nào! La-la-la-la-la-la-la-la-la-la-la-la (Yeah, yeah) La-la-la-la-la-la'),
('muon roi ma sao con|son tung m-tp', 'Muộn rồi mà sao còn Nhìn lên trần nhà rồi quay ra, lại quay vào Nằm trằn trọc vậy đến sáng mai Ôm tương tư nụ cười của ai đó Làm con tim ngô nghê như muốn khóc oà Vắt tay lên trên '),
('am tham ben em|son tung m-tp', 'Khi bên anh em thấy điều chi? Khi bên anh em thấy điều gì? Nước mắt rơi gần kề làn mi Chẳng còn những giây phút, chẳng còn những ân tình Gió mang em rời xa nơi đây Khi xa anh em nh'),
('di de tro ve|soobin hoang son', 'Tôi đang ở một nơi rất xa Nơi không có khói bụi thành phố Ở một nơi đẹp như mơ Trên cao êm êm mây trắng bay Lặng nhìn biển rộng sóng vỗ-ô Cuộc đời tôi là những chuyến đi dài Vượt s'),
('phia sau mot co gai|soobin hoang son', 'Nhiều khi anh mong được một lần nói ra hết tất cả thay vì Ngồi lặng im nghe em kể về anh ta bằng đôi mắt lấp lánh Đôi lúc em tránh ánh mắt của anh Vì dường như lúc nào em cũng hiểu'),
('hon ca yeu|duc phuc', 'Em hay hỏi anh Rằng anh yêu em nhiều không? Anh không biết phải nói thế nào Để đúng với cảm xúc trong lòng Khi anh nhìn em Là anh thấy cuộc đời anh Là quá khứ và cả tương lai Là hi'),
('anh nang cua anh|duc phuc', 'Từ bao lâu naу, anh cứ mãi cô đơn bơ vơ Bao lâu rồi? Ai đâu haу Ngàу cứ thế trôi qua miên man Riêng anh một mình nơi đâу Những phút giâу trôi qua tầm taу Ϲhờ một ai đó đến bên anh '),
('ai la nguoi thuong em|quan a.p', 'Người con gái anh từng yêu sao rồi Có một mình đi dưới mưa lúc buồn Lệ còn rơi khi ngồi xem thước phim buồn Ôm thật chặt vào ai khóc như đứa trẻ Người con gái anh từng yêu quên rồi'),
('bac phan|jack', 'J-A-C-K K-I-C-M, hallow Take it, one, two, let''s get it! Ai gieo tình này, ai mang tình này để lệ trên khóe mi cay Ai đưa về nhà, ai cho ngọc ngà giờ người xa cách ta Từng là một t'),
('hong nhan|jack', 'Ah-ah-ah-ah, ah-ah-ah Hah-hah-hah, hah-hah-hah, hah-hah Hah-hah-hah, hah-hah-hah-ah-ah-ah-ah, ah-ah Hah-hah-hah Và dòng thư tay em gửi trao anh ngày nào Giờ còn lại hư vô, em gửi a'),
('song gio|jack', 'Hồng trần trên đôi cánh tay, họa đời em trong phút giây Từ ngày thơ ấy còn ngủ mơ đến khi em thờ ơ (hờ, hờ) Lòng người anh đâu có hay, một ngày khi vỗ cánh bay Từ người yêu hóa thà'),
('dom dom|jack', 'Hah em đi mất rồi còn anh ở lại Hah Người giờ còn đây không Thuyền này còn liệu sang sông Buổi chiều dài mênh mông Lòng người giờ hoà hay đông Hồng mắt em cả bầu trời đỏ hoen Ta nh'),
('hoa hai duong|jack', 'Thiên hà trong vũ trụ này hoài xa xôi Riêng mình ôm góc trời hạt ngọc đêm rơi rồi Ai cũng mong hóa giàu vậy nghèo phần ai? Sai từ ngay lúc đầu tình bạc như vôi Tiếc là mình không c'),
('thien ly oi|jack', 'Ngày hôm nay trời trong xanh Đẹp như tranh Mình cùng dạo vòng quanh cả thế giới Đừng vội nhanh Một hành trình nhật ký yêu thương đời mình Hát vu vơ về tình đầu em ơi Ngày hôm ấy là'),
('gio|jank', 'Gió nhẹ sang, tôi ngỡ trời xuân Nắng hồng lên, tôi ngỡ đông tàn Ai có ngờ đâu đông vẫn còn đây Xuân chưa về Tôi ngỡ tình ta xanh ngát trời xuân Đâu biết ngày đông kéo đến bất chợt '),
('see tinh|hoang thuy linh', 'Uầy uầy uây uây Sao mới gặp lần đầu mà đầu mình quay quay? Anh ơi anh à Anh bỏ bùa gì mà lại làm em yêu vậy? Bae bae bae bae Em nói từ đầu baby can you stay Mai đi coi ngày Xem cướ'),
('de mi noi cho ma nghe|hoang thuy linh', 'Để Mị nói cho mà nghe Tâm hồn này chẳng để lặng lẽ Thương cha xót mẹ Thôi thì mặc phận đời mình chơi vơi Để Mị nói cho mà nghe Tết năm nay Mị vẫn còn trẻ Xuân đương tới rồi Nên Mị '),
('dau chi rieng em|my tam', 'Anh cứ nghĩ rằng em không biết những điều anh làm đằng sau lưng em Anh cứ nghĩ rằng em ngu ngốc Không hề hay biết những chuyện quẩn quanh Những chiếc hôn vụng trộm Những dòng tin n'),
('uoc gi|my tam', 'Em đã sống những đêm trời có ánh trăng chiếu vàng Em đã sống những đêm ngoài kia biển ru bờ cát Ước gì anh ở đây giờ này Ước gì anh cùng em chuyện trò Cùng nhau nghe sóng xô ghềnh '),
('hen uoc tu hu vo|my tam', 'Mình không tìm nhau Mà vô tình vương vấn sau tiếng ca chiều mưa Thân thương trong từng đong đưa mắt môi về em Mùa xuân ấy có nụ cười lấp lánh Ở gần bên anh Em vui như bao nhiêu lâu'),
('nguoi hay quen em di|my tam', 'Người yêu hỡi Dù gì cũng xa nhau rồi Ngày nào chiếc hôn bao đêm rã rời Giờ đã hết rồi, chẳng còn hơi ấm trên đầu môi Người yêu hỡi Giờ đây tiếng yêu phai phôi Chỉ còn những đêm cô '),
('minh cuoi nhau di|huynh james, pjnboys', 'Hay là mình, là mình, mình cưới nhau đi Hay là mình, là mình, mình cưới nhau đi Thanh xuân kia đi qua vội lắm ai ơi Cho anh xây tình nồng trọn kiếp bên em Hay là mình, là mình, mìn'),
('em gai mua|huong tram', 'Em đi rồi... Mưa trôi cả bầu trời nắng, trượt theo những nỗi buồn Thấm ướt lệ sầu môi đắng, vì đánh mất hy vọng Lần đầu gặp nhau dưới mưa, trái tim rộn ràng bởi ánh nhìn Tình cảm d'),
('co gai m52|huy, tung viu', 'Danny E.B, the producer Là cô gái hay mộng mơ (xinh đẹp như tiên giáng trần) Người đã khiến tôi thẫn thờ (cho ngày qua tôi thẫn thờ) Cho tôi nhung nhớ bao nhiêu, muốn nói với em ba'),
('tron tim|den', 'Có một cái cây trong một cái vườn Trên những tán cây nở rộ những đóa hoa Có hai đứa nhóc đang chơi trốn tìm Tìm hoài tìm mãi nên quên lối về Anh đi tìm thì em trốn, anh đi trốn em '),
('di ve nha|den, justatee', 'Đường về nhà là vào tim ta Dẫu nắng mưa gần xa Thất bát, vang danh Nhà vẫn luôn chờ ta (Ah) Đường về nhà là vào tim ta (Yeah, JustaTee) Dẫu có muôn trùng qua (Và Đen Vâu) Vật đổi, '),
('bai nay chill phet|den, min', 'I just wanna chill with you tonight And all the sorrow left behind uh-way Sometimes I feel lost in the crowd Life is full of ups and downs But it''s alright, I feel peaceful inside '),
('mang tien ve cho me|den', 'Mang tiền về cho mẹ Mang tiền về cho mẹ Mang tiền về cho mẹ Đừng mang ưu phiền về cho mẹ Mang tiền về cho mẹ Mang tiền về cho mẹ Mang tiền về cho mẹ Đừng mang ưu phiền về cho mẹ (o'),
('loi nho|den', 'Ay Ya Ya, Đen Vâu Em vào đời bằng đại lộ còn anh vào đời bằng lối nhỏ Anh nhớ mình đã từng thổ lộ, anh nhớ rằng em đã chối bỏ Anh nhớ chuyến xe buổi tối đó, trên xe chỉ có một ngườ'),
('ai chung tinh duoc mai|dinh tung huy', 'Bình minh ơi dậy chưa cà phê sáng với tôi được không Chơi vơi qua ngày đông sao thấy cô đơn và lạc lõng Đêm ơi đã ngủ chưa ngồi đây uống với tôi vài ly Say thì cứ say, yêu thì bỏ đ'),
('thang tu la loi noi doi cua em|ha anh tuan', 'Mùa xuân có em như chưa bắt đầu Và cơn gió đang khẽ mơn man lay từng nhành hoa rơi Em đã bước tới như em đã từng Chạy trốn với anh trên cánh đồng xanh Khúc nhạc hòa cùng nắng chiều'),
('thang may em nho anh|ha anh tuan', 'Tháng tư về, cánh hoa phai tàn Mắt ướt nhòe nỗi đau vô lường Tháng năm buồn vương những phố phường Thấp thoáng bóng người thương Bước trong cơn mưa rào tháng sáu Chợt nhớ tới khi x'),
('xuan thi|ha anh tuan', 'Gặp em trong những người bạn thân quen một ngày mùa đông Nhiều năm xa cách kể từ lúc ấy chẳng còn chờ mong Và thời gian đã nhuộm màu chính ta nên giờ mình khác xưa Đôi nếp nhăn đầu'),
('ha noi mua vang nhung con mua|cam van', 'Hà Nội mùa này vắng những cơn mưa Cái rét đầu đông khăn em hiu hiu gió lạnh Hoa sữa thôi rơi ta bên nhau một chiều tan lớp Đường Cổ Ngư xưa chầm chậm bước ta về Hà Nội mùa này chiề'),
('trai tim ben le|bang kieu', 'Em đã biết bao ngày bên em Là anh đã có bấy nhiêu ngày yêu em Nhưng em vẫn ngây thơ không biết tình anh Thầm yêu em nên tim đau rã rời Anh đã thấy bao người yêu em Tim anh đã nhức '),
('anh con no em|quang dung', '作词 : Anh Bang 作曲 : Anh Bang/Hoai Sa - Vinh Tam - Anh Khoa Anh còn nợ em 나는 아직 너에게 빚이 있어 Công viên ghế đá 공원 벤치에서 Công viên ghế đá 공원 벤치에서 Lá đổ chiều êm 잔잔한 오후 낙엽처럼 Và còn nợ em 그리'),
('tuoi da buon|quang dung', 'Trời còn làm mưa Mưa rơi mênh mang Từng ngón tay buồn Em mang em mang Đi về giáo đường Ngày chủ nhật buồn Còn ai còn ai Đóa hoa hồng Cài lên tóc mây Ôi đường phố dài Lời ru miệt mà'),
('mat troi be con|tran tien', 'Là la lá lá la là lá la la là la Là la lá lá la là lá la la là la Ngoài kia có cô bé nhìn qua khe Nghe tiếng đàn tiếng đàn tôi (lal lal lal) Ngoài kia có chú bé trèo cành me Mắt xo'),
('con buom xuan|ho quang hieu', 'Con bướm xinh con bướm xinh con bướm đa tình Đùa vui với lũ hoa bao hoa mai lan đang hòa mình Con én bay con én bay con én la đà Tựa bầy tiên nữ trong cung nhạc tình cha cha cha Xu'),
('hoa trinh nu|truong vu', 'Qua một rừng hoang gió núi theo sang giũ bụi đường trên vai Hái cây hoa dại lẻ loi bên đường gọi là hoa Trinh Nữ Hoa Trinh Nữ không mặn mà bằng nàng hồng kiêu sa Hoa đâu dám khoe m'),
('mua rung|truong vu', 'Mưa rừng ơi mưa rừng Hạt mưa nhớ ai mưa triền miên? Phải chăng mưa buồn vì tình đời? Mưa sầu vì lòng người duyên kiếp không lâu? Mưa từ đâu mưa về? Làm muôn lá hoa rơi tả tơi Tiếng'),
('an tinh sang trang|chau khai phong', 'Có bao giờ em thương anh thật lòng? Cách xa rồi cũng chỉ còn là số không Thế nào là đủ, bao nhiêu cho vừa? Tình cảm anh trao nay quá dư thừa Có bao giờ em nhớ thương một người? Chắ'),
('duyen minh lo|huong tram', 'Mình chia tay nhau từ đây Tổn thương trong em cũng nhiều rồi Tình yêu này đâu có lỗi gì Lỗi là thuộc về hai chúng ta Yêu gặp nhau là duyên Khi hết duyên tự đi Nghĩ vậy, cho nhẹ lòn'),
('ai hay chu ngo|lam chan khang', 'On the left corner Lâm Chấn Khang On the right corner Ty Phong Có những lúc anh đang chìm trong những giấc mơ dài Còn lại bao yêu thương cho em, lòng anh chẳng biết nói với ai Ngườ'),
('nang tho|hoang dung', 'Em, ngày em đánh rơi nụ cười vào anh Có nghĩ sau này em sẽ chờ Và vô tư cho đi hết những ngây thơ Anh, một người hát mãi những điều mong manh Lang thang tìm niềm vui đã lỡ Chẳng bu'),
('ai cho toi luong thien|trang phap; thu phuong; ninh duong lan ngoc', 'Ừ là mình đấy Bao năm người ta đồn tôi vì khác người ta Bờ môi thật xinh mà sao chẳng nói lời hoa Những lời hoa những gièm pha Ừ thì là mình đấy Những gì mọi người thấy chỉ là bề n'),
('nhu mot nguoi dung(feat. nguyen thac bao ngoc) (remix)|zheng yu, nguyen thac bao ngoc', 'Có lẽ xa một người trong lòng còn thương Chẳng khác như cuộc đời mọi điều vô hướng Đứng giữa yêu và dừng lại, em thật không biết Phải làm sao để anh sẽ thấy được vui Biết anh vẫn c'),
('chieu hom ay|jaykii', 'Chiều hôm ấy em nói với anh Rằng mình không nên gặp nhau nữa người ơi Em đâu biết anh đau thế nào Khoảng lặng phủ kín căn phòng ấy Tim anh như thắt lại Và mong đó chỉ là mơ vì anh '),
('nang am xa dan|son tung m-tp', 'Nắng ấm xa dần rồi Nắng ấm xa dần rồi Nắng ấm xa dần bỏ rơi để lại những giấc mơ Giữ lại đi, giữ giữ lại đi Nắng ấm xa dần rồi Nắng ấm xa dần rồi Nắng ấm xa dần, xa dần theo những '),
('chung ta khong thuoc ve nhau|son tung m-tp', 'Về, về, về nơi này Chúng ta không thuộc về nhau Chúng ta không thuộc về Về, về, về nơi này Niềm tin đã mất Giọt nước mắt cuốn kí ức anh chìm sâu Tình về nơi đâu Cô đơn đôi chân lạc'),
('dung lam trai tim anh dau|son tung m-tp', 'Hình như trong lòng anh đã không còn hình bóng ai ngoài em đâu Hằng đêm anh nằm thao thức suy tư, chẳng nhớ ai ngoài em đâu Vậy nên không cần nói nữa, yêu mà đòi nói trong vài ba c'),
('chung ta cua tuong lai|son tung m-tp', 'Liệu mai sau phai vội mau không bước bên cạnh nhau (không bước bên cạnh nhau) Thì ta có đau? (Thì ta có đau? Có đau?) Đôi mi nhoè phai ai sẽ lau? Ai sẽ đến lau nỗi đau này? Vô tâm '),
('anh sai roi|son tung m-tp', 'Nếu ngày mai em rời xa anh Anh không biết sống thế nào đây Con tim anh nhói đau từng cơn Anh biết hạt mưa không ngừng rơi khi thấy em buồn Xin thời gian hãy trở lại đi Anh không mu'),
('em dung di|son tung m-tp', 'Xin em đừng ra đi Con tim anh vẫn mãi yêu em như ngày nào (woh oh ho) Cho anh chạm nhẹ phút giây Làn gió dịu êm đưa em ra đi, em đang chốn nao (Cơn mưa kia vẫn rơi) Anh vẫn ngồi đâ'),
('co chac yeu la day|son tung m-tp', '(Thấp thoáng ánh mắt, thấp thoáng ánh mắt) (Thấp thoáng ánh mắt, thấp thoáng ánh mắt) Good boy Thấp thoáng ánh mắt đôi môi mang theo hương mê say Em cho anh tan trong miên man quên'),
('an nut nho... tha giac mo|son tung m-tp', 'Oh-oh-oh-oh-oh-oh-oh Eh-eh, oh-oh-oh-oh-oh-oh-oh Oh-oh-oh-oh-oh-oh-oh Oh-oh Sinh con ra bằng câu hát ru quen thuộc (quen thuộc) Dìu đôi chân mong con lớn khôn (mong con lớn khôn, n'),
('an nut nho...tha giac mo|son tung m-tp', 'Oh-oh-oh-oh-oh-oh-oh Eh-eh, oh-oh-oh-oh-oh-oh-oh Oh-oh-oh-oh-oh-oh-oh Oh-oh Sinh con ra bằng câu hát ru quen thuộc (quen thuộc) Dìu đôi chân mong con lớn khôn (mong con lớn khôn, n'),
('con mua xa dan|son tung m-tp', 'Chẳng quan tâm tương lai anh chẳng quan tâm đúng hay sai Chẳng quan tâm tương lai anh chẳng quan tâm đúng hay sai Còn đâu đây bao câu ca anh tặng em Tình yêu em mang cuốn lấp đi ba'),
('con mua ngang qua|son tung m-tp', 'Ladykillah, can you feel me? Youngpi (ah-ah-ah), ok Mua ngang qua, cơn mưa đi ngang qua Đừng làm rơi thêm, thêm, thêm Nnhiều giọt lệ còn đâu đây bao câu ca anh tặng em Tình yêu em '),
('nhu ngay hom qua|son tung m-tp', 'Cuối con đường là bầu trời xanh ấm êm (chu-la chu-la eh-eh) Bên tôi mỗi khi buồn, lặng lẽ xóa tan âu lo Gạt giọt nước mắt thăng trầm Niềm tin mãi luôn đong đầy Bài ca hát trọn đêm '),
('khong phai dang vua dau|son tung m-tp', 'Ở sau bờ vai là những sầu lo (ai theo tôi vậy?) Hình như đuổi theo là những nỗi lo Vô tư đi cứ bám vào anh này Suy tư anh u não cả tháng ngày Không may cho yêu tìm đến phải đúng th'),
('chung ta khong thuoc v|son tung m-tp', 'Thuộc về, về, về nơi này Chúng ta không thuộc về nhau (chúng ta không thuộc về nhau) Chúng ta không thuộc về (chúng ta không thuộc) Thuộc về, về, về nơi này Niềm tin đã mất, giọt n'),
('dung hoi em|my tam', 'Đừng hỏi em vì sao Tình yêu ta úa màu Đừng trách em vì sao giấc mơ tàn mau Đừng hỏi em vì sao Ngày đôi ta bắt đầu Một chiếc hôn nồng sâu đã đưa ta về đâu? Mình đã yêu nhau thật lâu'),
('vi em tat ca|my tam', 'Ngày ấy giá như đừng yêu Ngày ấy giá như vờ chẳng quan tâm gì nhau Thì chắc có lẽ giờ em sẽ không buồn đến thế đâu Ngày ấy anh như là mây Và trái tim em là gió vi vu khắp lối Mình '),
('biet khi nao gap lai|my tam', 'Câu chuyện xưa nay kết thúc thật rồi Những giấc mơ thả trôi giữa đời Và bây giờ đây ta cất bước ra đi Trách than gì nữa trước khi biệt ly? Hay là do ta đã quá vội vàng? Cho nên duy'),
('lanh lung|my tam', 'Lặng nghe tiếng mưa rơi ngoài hiên Giờ chỉ muốn tâm tư bình yên Mình trải qua bao nhiêu thời gian đau lòng rồi Phải cố gắng quên thôi, chuyện yêu đương nhức nhối Mà ta đã quá mong '),
('neu co buong tay|my tam', 'Nếu có buông tay, xin anh hãy buông thật chậm Đừng để em ngã xuống, vụn vỡ thành từng mảnh cô đơn Nếu có buông tay thì xin dứt khoát một lời Chớ quay lại và thương xót cho em Dù vế'),
('chuyen buon|my tam', 'Những tin nhắn đang chờ không còn muốn xem Giờ em đầy ắp nghi ngờ, cô độc giữa đêm Một phút mi nhắm ngơi nghỉ, mà toàn là nỗi đau Cứ thế câu chuyện như chưa lâu Giấc mơ đã khép lại'),
('anh chua tung biet|my tam', 'Chẳng thể ngờ là có lẽ mấy phút nữa Chuyện tình mình sẽ khác Quá đắn đo vì đôi tay ta Chưa từng buông chưa từng buông Ngày xưa ấy như nước hoa sau tai Em xức cho ta thơm nồng Dù qu'),
('co ay la ai|my tam', 'Đừng nói điều gì, đừng nói thêm chi Giọt nước trên mi, giờ đã tràn ly Người đã nơi đây, và đứng bên ai? Và chiếc hôn kia chẳng lẽ là sai? Và cô ấy là ai? Người anh yêu là ai? Em đâ'),
('dau the ma|my tam', 'Tiếc gì, rồi anh cũng giống như bao người ta Yêu nhau làm chi để bây giờ đau thế mà Yêu rất nhiều, giờ anh cũng nói câu đôi mình chia tay Tim em như chết theo bao lời anh nói Lời a'),
('neu anh di|my tam', 'Một câu nói anh muốn chia tay Em đã biết sẽ đau đớn như vậy Mà nước mắt đó vẫn rơi, không thể ngừng lại Tiếc nuối những gì cho cả hai Vì em biết đã có những sai lầm Dù em đã cố giữ'),
('anh sao buon|my tam', 'Nhớ ngày xa xưa, em vẫn thường mộng mơ Được hát vang lên khúc nhạc tình yêu Dẫu đời còn bao nhiêu nỗi buồn Còn bao khó khăn luôn kề bên em Tháng ngày phương xa nơi xứ lạ Mình em lặ'),
('em cho anh|my tam', 'Hoàng hôn như buông về trên con phố dài Chợt nghe cô đơn về trong đêm nhớ ai Chợt vây quanh em là bao tiếng nói cười Tình chưa kịp đầy mà mắt vội cay Bỗng thấy tiếc nuối những ngày'),
('''em cho anh|my tam', 'Hoàng hôn như buông về trên con phố dài Chợt nghe cô đơn về trong đêm nhớ ai Chợt vây quanh em là bao tiếng nói cười Tình chưa kịp đầy mà mắt vội cay Bỗng thấy tiếc nuối những ngày'),
('ve di anh|my tam', 'Nước mắt cứ rơi mãi không thôi khi ngồi mình nhớ anh Từ khi ta có nhau mình đã cách xa bao lần Nghìn trùng xa quá xa Từ giờ mình ngày buồn đêm nhớ nhung Giờ đây em ước chi rồi có m'),
('em con nho hay em da quen|my tam', 'Em còn nhớ hay em đã quên Nhớ Sài Gòn mưa rồi chợt nắng Nhớ phố xưa quen biết tên bàn chân Nhớ đèn đường từng đêm thao thức Sáng che em vòm lá me xanh Em còn nhớ hay em đã quên Bên'),
('em cua toi|my tam', 'Tôi yêu quê tôi, xanh xanh luỹ tre Quê hương tuổi thơ đi qua đời tôi Đường lang quanh co, sông thu êm đềm Thả diều đá bóng, nắng cháy giữa đồng Biển trời mênh mông, tôi bay ngày ấy'),
('hay noi voi em|my tam', 'Lắng nghe tiếng con tim. Biết em đã yêu anh. Tình là ánh nắng muôn màu. Tình là ánh mắt thiết tha trao nhau. Những phút bên anh, Hạnh phúc với bao lời yêu. Dù biết em vẫn yêu anh. '),
('dau yeu|my tam', 'Tình như thoáng mây để cơn gió cuốn trôi bao ngày Tình sao chóng phai để mình ta ôm sầu đắng Ngày nào còn thấy môi anh cười Giờ chỉ là dĩ vãng xa rồi Nhớ anh em vẫn thầm nhớ Một ma'),
('doi yeu|my tam', 'Em yêu anh rất đắm say Mặt trời rực rỡ như trên môi hồng Thời gian nào đó Tình yêu nào đó Cùng bao ngày tháng ta trao nhau những cuồng say Trong không gian ôi ngất ngây Nghe từng h'),
('yeu dai kho|my tam', 'Dù đã biết yêu người luôn trái ngang nhưng em vẫn yêu Vẫn yêu người thật lòng dù cho nhiều đớn đau Tình vẫn đó sâu tận trong trái tim sâu trong đáy lòng Sẽ cho anh rất nhiều dù cho'),
('hat yeu thuong|my tam', 'Hòa nhịp vui ngân vang khúc ca Ta hát cho người yêu nhau thiết tha Tháng năm đẹp người cùng nhau chia đều ước mơ Hát yêu người tình mộng mơ có khi vui buồn Đêm nay ánh trăng soi dị'),
('tinh nong|my tam', 'Đêm nay mưa rơi suốt đường về Mang theo cơn gió cuốn lời thề Cho em theo anh dẫu đường dài Nhớ thật nhiều dáng người bước nhẹ lối về Anh ơi xa nhau nhớ đừng buồn Em luôn mang đến n'),
('tinh me|my tam', 'Khẽ ngắt nụ hồng cài lên mái tóc xanh mẹ yêu Tóc rối một đời vì năm tháng chở che đời con Khi thơ ấu con nào đâu có biết Mẹ lặng lẽ trong ngàn nỗi muộn phiền Dù bao gió mưa tình mẹ'),
('tinh mo|my tam', 'Mình em trong cô đơn căn phòng khuya vắng lặng Thầm gọi tên anh trên môi nhưng đã xa Trời sao mưa rơi nhanh trái tim em lạnh lùng Vọng trong đêm đơn côi Người ơi anh ở chốn nào (bi'),
('tinh oi|my tam', 'Tình ơi, tình xa tít mù Nhớ không anh, chuyện mình ngày xưa Tìm trong tình yêu chôn kín Còn lại gì khi anh bước đi Nghe như mùa đông đã về Nghe như từng đêm vắng tênh Tim em còn ng'),
('mot chuyen tinh|my tam', 'Có đôi khi lòng anh tự hỏi phải chăng đã yêu Mỗi lúc em kề bên Mỗi lúc em cười vui Tim anh chợt như thắt lại... Anh Người cho em những nghĩ suy Có khi rất gần Có khi vô tình Bỗng t'),
('ban tinh cuoi|my tam', 'Mưa có rơi và nắng có phai Trên cuộc tình yêu anh ngày nào Ta đã yêu và ta đã mơ Mơ trăng sao đưa đến với người Một lần gặp gỡ đã như quen thuở nào Một lần gặp gỡ nhưng tình vẫn xa'),
('cho mot tinh yeu|my tam', 'Ngày mới quen nhau em nào hay đôi mình được gần nhau sống chung dưới trăng vàng Ngày tháng trôi qua em nhận ra tim mình ở gần anh em lại càng yêu anh Từ những lúc vui hay là lúc gi'),
('cam on nguoi tinh|my tam', 'Ngày chưa quen nhau đâu biết niềm đau Mùa xuân bao quanh nhìn đời bằng đôi mắt màu xanh Rồi ta quen nhau, những đêm hẹn ước Người tìm ta bằng những môi hôn nồng nàn Rồi ta yêu nhau'),
('doi mat nguoi xua|my tam', 'Chuyện tình của tôi tan vỡ từ lâu rồi tưởng không bao giờ còn nhớ Nhưng bỗng một hôm, trên đường ra phố thị tôi gặp người yêu ngày nào Đôi mắt ưu tư thât buồn nàng nhìn tôi, rồi qu'),
('nguoi yeu dau oi|my tam', 'Người yêu ơi hãy đến với em đêm này Đừng để em theo cơn gió cuốn mãi một đời bềnh bồng Cho mắt khô khi thu sầu gọi thương nhớ Tìm đâu thấy ước mơ chân tình, để em giữ trong lòng Ng'),
('hat cho nguoi o lai|my tam', 'Ngày nào em đến bên anh Tim anh ngẩn ngơ chợt buồn vu vơ Em rất vô tư, em quá ngây thơ Làm anh thẫn thờ Rồi em cất bước ra đi Tim anh giá băng, hồn anh chết lặng Em đã ra đi, không'),
('nho|my tam', 'Một vì sao rớt xuống trong đêm Như anh đến ôm em bên thềm Dường như em chỉ muốn anh thôi Ngồi lặng im, lắng nghe anh cười anh nói Anh như là gió, vừa mới đến đó thế nhưng đã xa rồi'),
('mua va noi nho|my tam', 'Ngày nắng, vội tắt, hạt mưa bỡ ngỡ về Và gió lang thang lời dấu yêu đã muốn quên đi Mưa rơi, nghìn hạt trắng trong phai mờ con phố Mưa rơi nhạt nhoà trước sân, còn em nơi đây, ướt '),
('nho anh that nhieu|my tam', 'Phố vắng chốn xưa riêng em nơi đây ôm bao cơn mơ ta yêu ngày nào Nay nỡ lãng quên sao anh từng lời nguyện cầu được mãi bên nhau Ôm bao nỗi nhớ với lẻ loi mãi cô đơn bước đi đến phư'),
('nho ve ha noi|my tam', 'Dù có đi bốn phương trời Lòng vẫn nhớ về Hà Nội Hà Nội của ta, thủ đô yêu dấu Một thời đạn bom, một thời hòa bình Nhớ phố Thâm Nghiêm rợp bóng cây Tiếng ve ru những trưa hè Và nhớ '),
('thanh pho tinh yeu va noi nho|my tam', 'Có từ bao giờ hàng me xanh ngát Mà nay đứng đó cho em làm thơ Con đường ta qua đến nay bao tuổi Em qua trăm buổi em lại ngàn lần Mà sao bối rối khi cầm tay nhau Em ơi hãy lắng nghe'),
('mua khoc|my tam', '(Em trôi đi vào trong nỗi nhớ Mưa rơi cho càng thêm buốt giá) Đêm đong đầy trong mắt Tình ta sao giờ xa vắng Người đi không về đây nữa Rồi đêm mang về đây nỗi u sầu Để em trôi đi v'),
('mot ngay mua dong|my tam', 'Rồi một ngày trời không biếc xanh Rồi một ngày hàng cây vắng tanh Và cơn gió mang mùa đông tới Cuốn bay theo nắm lá vàng rơi Bờ cỏ này giọt sương đã tan Bậc thềm này còn in dấu châ'),
('mua dong cua anh|my tam', 'Ngày nào em yêu anh em đã quen trong cay đắng tuyệt vời Ngày nào anh yêu em anh đã quen với trời hạnh phúc mới Anh ơi đông lại về từ trăm năm lạnh giá Tim em như ngừng thở từ sau â'),
('lai mot dem mua|my tam', 'Đêm, nghe tiếng mưa rơi lạnh buốt lòng mình Trong đêm vắng còn em thao thức nghẹn ngào Hỡi anh Tình yêu phải đâu như giấc mơ Để em bơ vơ tìm về thương nhớ Anh, em viết tên anh vào '),
('danh thuc mua thu|my tam', 'Từng chiếc lá rơi, gọi mùa thu đến đây rồi Đánh thức tôi lời tình yêu nói hôm nào Và những khát khao chuyện tình như sóng thét gào Cuốn xô ta bằng tình yêu đã phôi pha Rồi mùa thu '),
('giac mo mua he|my tam', 'Mùa hè mây bay mây bay đến vô cùng xa Mùa hè xanh tươi xanh tươi đến vô cùng xanh Ngồi bên anh giữa cõi lênh đênh Tựa vai anh nghe sóng ru êm Dập dìu thuyền về nơi bến xa Mình dìu '),
('giac mo mua thu|my tam', 'Người đi ra đi mãi mãi, chốn xưa tôi còn mong chờ Người đi ra đi mãi mãi, vẫn không phai mờ dấu chân Lòng tôi chiếc lá trên cành thu về héo khô Tôi còn nhớ ai mỗi khi chiều rơi Ngư'),
